function productDefaults(){defaults({terms:{},notes:[],edit:''})}
function plusDays(n){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function productRender(){for(const b of state.books){if(b.borrower&&!p.terms[b.id])p.terms[b.id]={due:plusDays(14),renewals:0};if(!b.borrower)delete p.terms[b.id]}const edit=state.books.find(x=>x.id===p.edit);put(`<div class="grid"><div>${box('借阅期限与续借',rows(state.books.filter(x=>x.borrower),b=>`<div class="item"><div><strong>${esc(b.title)}</strong><p>${esc(b.borrower)} · 应还 ${p.terms[b.id].due} ${p.terms[b.id].due<today()?' / 已超过约定日期':''}</p><p>已续借 ${p.terms[b.id].renewals} 次</p></div><button data-renew="${b.id}" class="small">从今天续借7天</button></div>`)+`<form id="due-date" class="stack"><label>借阅图书<select name="id">${state.books.filter(x=>x.borrower).map(b=>`<option value="${b.id}">${esc(b.title)}</option>`).join('')}</select></label>${dateField('due')}<button>修改应还日期</button></form>`)}${box('我的阅读推荐',`<form id="reading-note" class="stack"><label>选择图书<select name="book">${state.books.map(b=>`<option>${esc(b.title)}</option>`).join('')}</select></label>${field('我推荐给怎样的读者','reader','text','','required maxlength="60"')}${field('推荐理由（不要剧透）','reason','text','','required maxlength="200"')}<button>发布到本机推荐墙</button></form>${rows(p.notes,x=>`<div class="item"><div><h3>${esc(x.book)}</h3><p>适合：${esc(x.reader)}<br>${esc(x.reason)}</p></div><button data-note-delete="${x.id}" class="small">删除</button></div>`)}`)}</div><div>${box('图书维护',state.books.map(b=>`<div class="item"><span>${esc(b.title)}</span><div class="row"><button data-edit="${b.id}" class="small">编辑</button><button data-remove="${b.id}" class="small" ${b.borrower?'disabled':''}>下架</button></div></div>`).join('')+note('借出的图书需先归还，再下架。'))}${edit?box('修改图书',`<form id="book-edit" class="stack">${field('书名','title','text',edit.title,'required maxlength="80"')}${select('标签','tag',['冒险','科学','童话','自然'],edit.tag)}<button>保存图书</button></form>`):''}${box('书架资料',btn('导出藏书 CSV','books-csv',''))}</div></div>`);deleteButtons('renew',id=>{p.terms[id].due=plusDays(7);p.terms[id].renewals++;commit()});form('due-date',v=>{if(!p.terms[v.id])return toast('暂无借出的图书');p.terms[v.id].due=v.due;commit()});form('reading-note',v=>{p.notes.push({...v,id:uid()});commit()});deleteButtons('note-delete',id=>{p.notes=p.notes.filter(x=>x.id!==id);commit()});deleteButtons('edit',id=>{p.edit=id;commit()});deleteButtons('remove',id=>{const b=state.books.find(x=>x.id===id);if(b.borrower)return;state.books=state.books.filter(x=>x.id!==id);p.edit='';commit()});form('book-edit',v=>{if(state.books.some(x=>x!==edit&&x.title===v.title.trim()))return toast('已有同名图书');Object.assign(edit,v);p.edit='';commit()});on('books-csv',()=>exportCSV('家庭书架.csv',['书名','标签','借阅者代号','应还日期'],state.books.map(x=>[x.title,x.tag,x.borrower,p.terms[x.id]?.due||''])))}
